from sympy import QQ, sqrt, cos, pi, minimal_polynomial, Matrix, Poly, symbols
x = symbols('x')
for extensions, expected in [((sqrt(2), sqrt(3)), 2304), ((sqrt(2), sqrt(5)), 1600), ((sqrt(2), 2*cos(2*pi/7)), 1229312)]:
    K = QQ.algebraic_field(*extensions)
    assert K.discriminant() == expected
    basis = K.integral_basis()
    for element in K.integral_basis(fmt='sympy'):
        polynomial = Poly(minimal_polynomial(element, x), x)
        assert polynomial.LC() == 1
        assert polynomial.domain == QQ or polynomial.domain.is_ZZ
    K.maximal_order().compute_mult_tab()
    for p in [2, 3, 5, 7, 41]:
        assert sum(prime.e * prime.f for prime in K.primes_above(p)) == len(basis)
    print(K, 'discriminant:', K.discriminant(), 'integral basis and prime decompositions verified')
PY","yield_time_ms":1000,"max_output_tokens":2500}));
